 // Large category data calculation is performance sensitive, and ticks and label
 // probably will be fetched multiple times. So we cache the result.
 // axis is created each time during a ec process, so we do not need to clear cache.
+// But the scale extent of an existing axis can change (for example when dataZoom
+// changes the window), and the cached result of the previous extent must not be
+// reused then, otherwise ticks and labels of values that are not in the window
+// anymore would be rendered outside of the axis.
 function getListCache(axis: Axis, prop: 'ticks'): InnerStore['ticks'];
 function getListCache(axis: Axis, prop: 'labels'): InnerStore['labels'];
 function getListCache(axis: Axis, prop: 'ticks' | 'labels') {
@@ -248,16 +262,32 @@ function getListCache(axis: Axis, prop: 'ticks' | 'labels') {
     return inner(axis)[prop] || (inner(axis)[prop] = []);
