-function listCacheGet<T>(cache: InnerTickLabelCache<T>, key: CacheKey): T {
+function listCacheGet<T>(cache: InnerTickLabelCache<T>, key: CacheKey, scaleExtent: number[]): T {
     for (let i = 0; i < cache.length; i++) {
-        if (cache[i].key === key) {
+        if (cache[i].key === key
+            && cache[i].scaleExtent0 === scaleExtent[0]
+            && cache[i].scaleExtent1 === scaleExtent[1]
