265	function listCacheGet<T>(cache: InnerTickLabelCache<T>, key: CacheKey, scaleExtent: number[]): T {
266	    for (let i = 0; i < cache.length; i++) {
267	        if (cache[i].key === key
268	            && cache[i].scaleExtent0 === scaleExtent[0]
269	            && cache[i].scaleExtent1 === scaleExtent[1]
270	        ) {
271	            return cache[i].value;
272	        }
273	    }
274	}
