276	function listCacheSet<T>(cache: InnerTickLabelCache<T>, key: CacheKey, scaleExtent: number[], value: T): T {
277	    const item = {
278	        key: key,
279	        value: value,
280	        scaleExtent0: scaleExtent[0],
281	        scaleExtent1: scaleExtent[1]
282	    };
283	    for (let i = 0; i < cache.length; i++) {
284	        // Replace the outdated result of the same key rather than piling them up.
285	        if (cache[i].key === key) {
286	            cache[i] = item;
287	            return value;
288	        }
289	    }
290	    cache.push(item);
291	    return value;
292	}
