301	/**
302	 * Calculate interval for category axis ticks and labels.
303	 * To get precise result, at least one of `getRotate` and `isHorizontal`
304	 * should be implemented in axis.
305	 */
306	export function calculateCategoryInterval(axis: Axis) {
307	    const params = fetchAutoCategoryIntervalCalculationParams(axis);
308	    const labelFormatter = makeLabelFormatter(axis);
309	    const rotation = (params.axisRotate - params.labelRotate) / 180 * Math.PI;
310	
311	    const ordinalScale = axis.scale as OrdinalScale;
312	    const ordinalExtent = ordinalScale.getExtent();
313	    // Providing this method is for optimization:
314	    // avoid generating a long array by `getTicks`
315	    // in large category data case.
316	    const tickCount = ordinalScale.count();
317	
318	    if (ordinalExtent[1] - ordinalExtent[0] < 1) {
319	        return 0;
320	    }
321	
322	    let step = 1;
323	    // Simple optimization. Empirical value: tick count should less than 40.
324	    if (tickCount > 40) {
325	        step = Math.max(1, Math.floor(tickCount / 40));
326	    }
327	    let tickValue = ordinalExtent[0];
328	    const unitSpan = axis.dataToCoord(tickValue + 1) - axis.dataToCoord(tickValue);
329	    const unitW = Math.abs(unitSpan * Math.cos(rotation));
330	    const unitH = Math.abs(unitSpan * Math.sin(rotation));
331	
332	    let maxW = 0;
333	    let maxH = 0;
334	
335	    // Caution: Performance sensitive for large category data.
336	    // Consider dataZoom, we should make appropriate step to avoid O(n) loop.
337	    for (; tickValue <= ordinalExtent[1]; tickValue += step) {
338	        let width = 0;
339	        let height = 0;
340	
341	        // Not precise, do not consider align and vertical align
342	        // and each distance from axis line yet.
343	        const rect = textContain.getBoundingRect(
344	            labelFormatter({ value: tickValue }), params.font, 'center', 'top'
345	        );
346	        // Magic number
347	        width = rect.width * 1.3;
348	        height = rect.height * 1.3;
349	
350	        // Min size, void long loop.
351	        maxW = Math.max(maxW, width, 7);
352	        maxH = Math.max(maxH, height, 7);
353	    }
354	
355	    let dw = maxW / unitW;
356	    let dh = maxH / unitH;
357	    // 0/0 is NaN, 1/0 is Infinity.
358	    isNaN(dw) && (dw = Infinity);
359	    isNaN(dh) && (dh = Infinity);
360	    let interval = Math.max(0, Math.floor(Math.min(dw, dh)));
361	
362	    const cache = inner(axis.model);
363	    const axisExtent = axis.getExtent();
364	    const lastAutoInterval = cache.lastAutoInterval;
365	    const lastTickCount = cache.lastTickCount;
366	
367	    // Use cache to keep interval stable while moving zoom window,
368	    // otherwise the calculated interval might jitter when the zoom
369	    // window size is close to the interval-changing size.
370	    // For example, if all of the axis labels are `a, b, c, d, e, f, g`.
371	    // The jitter will cause that sometimes the displayed labels are
372	    // `a, d, g` (interval: 2) sometimes `a, c, e`(interval: 1).
373	    if (lastAutoInterval != null
374	        && lastTickCount != null
375	        && Math.abs(lastAutoInterval - interval) <= 1
376	        && Math.abs(lastTickCount - tickCount) <= 1
377	        // Always choose the bigger one, otherwise the critical
378	        // point is not the same when zooming in or zooming out.
379	        && lastAutoInterval > interval
380	        // If the axis change is caused by chart resize, the cache should not
381	        // be used. Otherwise some hidden labels might not be shown again.
382	        && cache.axisExtent0 === axisExtent[0]
383	        && cache.axisExtent1 === axisExtent[1]
384	    ) {
385	        interval = lastAutoInterval;
386	    }
387	    // Only update cache if cache not used, otherwise the
388	    // changing of interval is too insensitive.
389	    else {
390	        cache.lastTickCount = tickCount;
391	        cache.lastAutoInterval = interval;
392	        cache.axisExtent0 = axisExtent[0];
393	        cache.axisExtent1 = axisExtent[1];
394	    }
395	
396	    return interval;
397	}
