403	            ? axis.getRotate()
404	            : ((axis as Axis2D).isHorizontal && !(axis as Axis2D).isHorizontal())
405	            ? 90
406	            : 0,
407	        labelRotate: labelModel.get('rotate') || 0,
408	        font: labelModel.getFont()
409	    };
410	}
