422	function makeLabelsByNumericCategoryInterval(axis: Axis, categoryInterval: number, onlyTick?: boolean) {
423	    const labelFormatter = makeLabelFormatter(axis);
424	    const ordinalScale = axis.scale as OrdinalScale;
425	    const ordinalExtent = ordinalScale.getExtent();
426	    const labelModel = axis.getLabelModel();
