446	    // (2) Scales except category always contain min max label so
447	    // do not need to perform this process.
448	    const showAllLabel = shouldShowAllLabels(axis);
449	    const includeMinLabel = labelModel.get('showMinLabel') || showAllLabel;
450	    const includeMaxLabel = labelModel.get('showMaxLabel') || showAllLabel;
451	
452	    if (includeMinLabel && startTick !== ordinalExtent[0]) {
