454	    }
455	
456	    // Optimize: avoid generating large array by `ordinalScale.getTicks()`.
457	    let tickValue = startTick;
458	    for (; tickValue <= ordinalExtent[1]; tickValue += step) {
459	        addItem(tickValue);
460	    }
461	
462	    if (includeMaxLabel && tickValue - step !== ordinalExtent[1]) {
463	        addItem(ordinalExtent[1]);
464	    }
