469	            ? tickValue
470	            : {
471	                formattedLabel: labelFormatter(tickObj),
472	                rawLabel: ordinalScale.getLabel(tickObj),
473	                tickValue: tickValue
474	            }
475	        );
476	    }
477	
478	    return result;
479	}
